            assert!(planning.is_paused());
            assert_eq!(planning.notes.findings.len(), 1);
            assert_eq!(planning.notes.findings[0].state, super::FindingState::Done);
            // Proposed, never added by itself.
            assert_eq!(planning.proposals.len(), 1);
