    Failed,
    Stopped,
}

impl FindingState {
    fn label(self) -> &'static str {
        match self {
            Self::Done => "Done",
            Self::Failed => "Failed",
            // Ended early, as stopped.
            Self::Stopped => "Incomplete",
        }
    }
}

